   412 |     // As a special case, the "directory" may refer directly to an
   413 |     // IWAD file if the path comes from DOOMWADDIR or DOOMWADPATH.
   414 | 
   415 |     if (DirIsFile(dir, iwadname) && M_FileExists(dir))
   416 |     {
