   421 |     // this directory, and check if it exists.
   422 | 
   423 |     if (!strcmp(dir, "."))
   424 |     {
   425 |         filename = strdup(iwadname);
   426 |     }
   427 |     else
   428 |     {
   429 |         filename = M_StringJoin(dir, DIR_SEPARATOR_S, iwadname, NULL);
