#include "my_stdlib.h"

#include <errno.h>
#include <strings.h>
#include <time.h>

/*
 * Tiny freestanding C runtime for vm.js.
 *
 * The VM intentionally implements a small, non-Linux syscall ABI:
 *   0 read, 1 write, 2 open, 3 close, 8 seek, 38 rename, 201 time.
 * Keeping the ABI here means Doom itself can remain ordinary C code.
 */

static int vm_syscall3(int number, uintptr_t arg0, uintptr_t arg1,
                       uintptr_t arg2)
{
    register uintptr_t v0 __asm__("$2") = (uintptr_t) number;
    register uintptr_t a0 __asm__("$4") = arg0;
    register uintptr_t a1 __asm__("$5") = arg1;
    register uintptr_t a2 __asm__("$6") = arg2;

    __asm__ volatile ("syscall"
                      : "+r" (v0)
                      : "r" (a0), "r" (a1), "r" (a2)
                      : "memory");

    return (int) v0;
}

/* ------------------------------------------------------------------------- */
/* errno                                                                     */
/* ------------------------------------------------------------------------- */

static int mini_errno;

int *__errno_location(void)
{
    return &mini_errno;
}

/* ------------------------------------------------------------------------- */
/* memory and strings                                                        */
/* ------------------------------------------------------------------------- */

void *memcpy(void *dest, const void *src, size_t count)
{
    unsigned char *d = dest;
    const unsigned char *s = src;

    while (count-- != 0)
    {
        *d++ = *s++;
    }

    return dest;
}

void *memmove(void *dest, const void *src, size_t count)
{
    unsigned char *d = dest;
    const unsigned char *s = src;

    if (d < s)
    {
        while (count-- != 0)
        {
            *d++ = *s++;
        }
    }
    else if (d > s)
    {
        d += count;
        s += count;

        while (count-- != 0)
        {
            *--d = *--s;
        }
    }

    return dest;
}

void *memset(void *dest, int value, size_t count)
{
    unsigned char *d = dest;

    while (count-- != 0)
    {
        *d++ = (unsigned char) value;
    }

    return dest;
}

int memcmp(const void *left, const void *right, size_t count)
{
    const unsigned char *a = left;
    const unsigned char *b = right;

    while (count-- != 0)
    {
        if (*a != *b)
        {
            return (int) *a - (int) *b;
        }

        ++a;
        ++b;
    }

    return 0;
}

void *memchr(const void *ptr, int value, size_t count)
{
    const unsigned char *p = ptr;

    while (count-- != 0)
    {
        if (*p == (unsigned char) value)
        {
            return (void *) p;
        }

        ++p;
    }

    return NULL;
}

size_t strlen(const char *s)
{
    const char *start = s;

    while (*s != '\0')
    {
        ++s;
    }

    return (size_t) (s - start);
}

size_t strnlen(const char *s, size_t maximum)
{
    size_t result = 0;

    while (result < maximum && s[result] != '\0')
    {
        ++result;
    }

    return result;
}

char *strcpy(char *dest, const char *src)
{
    char *result = dest;

    do
    {
        *dest++ = *src;
    } while (*src++ != '\0');

    return result;
}

char *strncpy(char *dest, const char *src, size_t count)
{
    char *result = dest;

    while (count != 0 && *src != '\0')
    {
        *dest++ = *src++;
        --count;
    }

    while (count-- != 0)
    {
        *dest++ = '\0';
    }

    return result;
}

char *strcat(char *dest, const char *src)
{
    strcpy(dest + strlen(dest), src);
    return dest;
}

char *strncat(char *dest, const char *src, size_t count)
{
    char *out = dest + strlen(dest);

    while (count-- != 0 && *src != '\0')
    {
        *out++ = *src++;
    }

    *out = '\0';
    return dest;
}

int strcmp(const char *left, const char *right)
{
    while (*left != '\0' && *left == *right)
    {
        ++left;
        ++right;
    }

    return (unsigned char) *left - (unsigned char) *right;
}

int strncmp(const char *left, const char *right, size_t count)
{
    while (count != 0)
    {
        if (*left != *right || *left == '\0')
        {
            return (unsigned char) *left - (unsigned char) *right;
        }

        ++left;
        ++right;
        --count;
    }

    return 0;
}

#undef tolower
#undef toupper
#undef isspace
#undef isalpha
#undef isdigit
#undef isalnum
#undef isxdigit
#undef isupper
#undef islower
#undef isprint
#undef isgraph
#undef ispunct
#undef iscntrl

int tolower(int c)
{
    return c >= 'A' && c <= 'Z' ? c + ('a' - 'A') : c;
}

int toupper(int c)
{
    return c >= 'a' && c <= 'z' ? c - ('a' - 'A') : c;
}

int isspace(int c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\r'
        || c == '\f' || c == '\v';
}

int isalpha(int c)
{
    return (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z');
}

int isdigit(int c)
{
    return c >= '0' && c <= '9';
}

int isalnum(int c)
{
    return isalpha(c) || isdigit(c);
}

int isxdigit(int c)
{
    return isdigit(c) || (c >= 'a' && c <= 'f')
        || (c >= 'A' && c <= 'F');
}

int isupper(int c)
{
    return c >= 'A' && c <= 'Z';
}

int islower(int c)
{
    return c >= 'a' && c <= 'z';
}

int isprint(int c)
{
    return c >= 0x20 && c <= 0x7e;
}

int isgraph(int c)
{
    return c >= 0x21 && c <= 0x7e;
}

int ispunct(int c)
{
    return isgraph(c) && !isalnum(c);
}

int iscntrl(int c)
{
    return (c >= 0 && c < 0x20) || c == 0x7f;
}

int strcasecmp(const char *left, const char *right)
{
    while (*left != '\0' && tolower((unsigned char) *left)
                          == tolower((unsigned char) *right))
    {
        ++left;
        ++right;
    }

    return tolower((unsigned char) *left) - tolower((unsigned char) *right);
}

int strncasecmp(const char *left, const char *right, size_t count)
{
    while (count != 0)
    {
        int a = tolower((unsigned char) *left);
        int b = tolower((unsigned char) *right);

        if (a != b || a == 0)
        {
            return a - b;
        }

        ++left;
        ++right;
        --count;
    }

    return 0;
}

char *strchr(const char *s, int value)
{
    for (;; ++s)
    {
        if (*s == (char) value)
        {
            return (char *) s;
        }

        if (*s == '\0')
        {
            return NULL;
        }
    }
}

char *strrchr(const char *s, int value)
{
    const char *result = NULL;

    do
    {
        if (*s == (char) value)
        {
            result = s;
        }
    } while (*s++ != '\0');

    return (char *) result;
}

char *strstr(const char *haystack, const char *needle)
{
    size_t needle_len = strlen(needle);

    if (needle_len == 0)
    {
        return (char *) haystack;
    }

    while (*haystack != '\0')
    {
        if (strncmp(haystack, needle, needle_len) == 0)
        {
            return (char *) haystack;
        }

        ++haystack;
    }

    return NULL;
}

size_t strspn(const char *s, const char *accept)
{
    size_t result = 0;

    while (s[result] != '\0' && strchr(accept, s[result]) != NULL)
    {
        ++result;
    }

    return result;
}

size_t strcspn(const char *s, const char *reject)
{
    size_t result = 0;

    while (s[result] != '\0' && strchr(reject, s[result]) == NULL)
    {
        ++result;
    }

    return result;
}

char *strpbrk(const char *s, const char *accept)
{
    while (*s != '\0')
    {
        if (strchr(accept, *s) != NULL)
        {
            return (char *) s;
        }

        ++s;
    }

    return NULL;
}

/* ------------------------------------------------------------------------- */
/* allocator                                                                 */
/* ------------------------------------------------------------------------- */

typedef struct heap_block_s heap_block_t;

struct heap_block_s
{
    uint32_t size;
    uint32_t free;
    heap_block_t *next;
};

extern unsigned char __heap_start[];

static heap_block_t *heap_first;
static heap_block_t *heap_last;
static uintptr_t heap_cursor;

#define HEAP_END ((uintptr_t) 0x30000000u)
#define HEAP_ALIGN 8u

static size_t align_heap_size(size_t size)
{
    return (size + HEAP_ALIGN - 1u) & ~(HEAP_ALIGN - 1u);
}

void *malloc(size_t size)
{
    heap_block_t *block;
    size_t wanted;

    if (size == 0)
    {
        size = 1;
    }

    wanted = align_heap_size(size);

    for (block = heap_first; block != NULL; block = block->next)
    {
        if (block->free && block->size >= wanted)
        {
            if (block->size >= wanted + sizeof(heap_block_t) + HEAP_ALIGN)
            {
                heap_block_t *split = (heap_block_t *)
                    ((unsigned char *) (block + 1) + wanted);

                split->size = block->size - wanted - sizeof(heap_block_t);
                split->free = 1;
                split->next = block->next;
                block->size = wanted;
                block->next = split;

                if (heap_last == block)
                {
                    heap_last = split;
                }
            }

            block->free = 0;
            return block + 1;
        }
    }

    if (heap_cursor == 0)
    {
        heap_cursor = ((uintptr_t) __heap_start + HEAP_ALIGN - 1u)
                    & ~(uintptr_t) (HEAP_ALIGN - 1u);
    }

    if (wanted > HEAP_END - heap_cursor - sizeof(heap_block_t))
    {
        errno = ENOMEM;
        return NULL;
    }

    block = (heap_block_t *) heap_cursor;
    block->size = wanted;
    block->free = 0;
    block->next = NULL;
    heap_cursor += sizeof(heap_block_t) + wanted;

    if (heap_last != NULL)
    {
        heap_last->next = block;
    }
    else
    {
        heap_first = block;
    }

    heap_last = block;
    return block + 1;
}

void free(void *ptr)
{
    heap_block_t *block;
    heap_block_t *scan;

    if (ptr == NULL)
    {
        return;
    }

    block = ((heap_block_t *) ptr) - 1;
    block->free = 1;

    for (scan = heap_first; scan != NULL && scan->next != NULL; )
    {
        unsigned char *expected = (unsigned char *) (scan + 1) + scan->size;

        if (scan->free && scan->next->free
         && expected == (unsigned char *) scan->next)
        {
            heap_block_t *next = scan->next;
            scan->size += sizeof(heap_block_t) + next->size;
            scan->next = next->next;

            if (heap_last == next)
            {
                heap_last = scan;
            }
        }
        else
        {
            scan = scan->next;
        }
    }
}

void *calloc(size_t count, size_t size)
{
    size_t total;
    void *result;

    if (size != 0 && count > (size_t) -1 / size)
    {
        errno = ENOMEM;
        return NULL;
    }

    total = count * size;
    result = malloc(total);

    if (result != NULL)
    {
        memset(result, 0, total);
    }

    return result;
}

void *realloc(void *ptr, size_t size)
{
    heap_block_t *block;
    void *result;

    if (ptr == NULL)
    {
        return malloc(size);
    }

    if (size == 0)
    {
        free(ptr);
        return NULL;
    }

    block = ((heap_block_t *) ptr) - 1;

    if (block->size >= size)
    {
        return ptr;
    }

    result = malloc(size);

    if (result != NULL)
    {
        memcpy(result, ptr, block->size);
        free(ptr);
    }

    return result;
}

char *strdup(const char *s)
{
    size_t size = strlen(s) + 1;
    char *result = malloc(size);

    if (result != NULL)
    {
        memcpy(result, s, size);
    }

    return result;
}

char *strndup(const char *s, size_t maximum)
{
    size_t size = strnlen(s, maximum);
    char *result = malloc(size + 1);

    if (result != NULL)
    {
        memcpy(result, s, size);
        result[size] = '\0';
    }

    return result;
}

/* ------------------------------------------------------------------------- */
/* integer conversion                                                        */
/* ------------------------------------------------------------------------- */

static int digit_value(int c)
{
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'z') return c - 'a' + 10;
    if (c >= 'A' && c <= 'Z') return c - 'A' + 10;
    return -1;
}

unsigned long strtoul(const char *s, char **end, int base)
{
    const char *start;
    unsigned long value = 0;
    int negative = 0;
    int any = 0;

    while (isspace((unsigned char) *s)) ++s;

    if (*s == '+' || *s == '-')
    {
        negative = *s == '-';
        ++s;
    }

    if ((base == 0 || base == 16) && s[0] == '0'
     && (s[1] == 'x' || s[1] == 'X'))
    {
        base = 16;
        s += 2;
    }
    else if (base == 0 && *s == '0')
    {
        base = 8;
    }
    else if (base == 0)
    {
        base = 10;
    }

    start = s;

    for (;; ++s)
    {
        int digit = digit_value((unsigned char) *s);

        if (digit < 0 || digit >= base)
        {
            break;
        }

        value = value * (unsigned long) base + (unsigned long) digit;
        any = 1;
    }

    if (end != NULL)
    {
        *end = (char *) (any ? s : start);
    }

    return negative ? (unsigned long) (0ul - value) : value;
}

long strtol(const char *s, char **end, int base)
{
    return (long) strtoul(s, end, base);
}

long long strtoll(const char *s, char **end, int base)
{
    int negative = 0;
    unsigned long long value = 0;
    const char *start;
    int any = 0;

    while (isspace((unsigned char) *s)) ++s;

    if (*s == '+' || *s == '-')
    {
        negative = *s == '-';
        ++s;
    }

    if ((base == 0 || base == 16) && s[0] == '0'
     && (s[1] == 'x' || s[1] == 'X'))
    {
        base = 16;
        s += 2;
    }
    else if (base == 0 && *s == '0')
    {
        base = 8;
    }
    else if (base == 0)
    {
        base = 10;
    }

    start = s;

    for (;; ++s)
    {
        int digit = digit_value((unsigned char) *s);

        if (digit < 0 || digit >= base) break;
        value = value * (unsigned) base + (unsigned) digit;
        any = 1;
    }

    if (end != NULL) *end = (char *) (any ? s : start);
    return negative ? -(long long) value : (long long) value;
}

unsigned long long strtoull(const char *s, char **end, int base)
{
    return (unsigned long long) strtoll(s, end, base);
}

int atoi(const char *s) { return (int) strtol(s, NULL, 10); }
long atol(const char *s) { return strtol(s, NULL, 10); }
long long atoll(const char *s) { return strtoll(s, NULL, 10); }

int abs(int value) { return value < 0 ? -value : value; }
long labs(long value) { return value < 0 ? -value : value; }
long long llabs(long long value) { return value < 0 ? -value : value; }

/* ------------------------------------------------------------------------- */
/* formatted output                                                          */
/* ------------------------------------------------------------------------- */

typedef struct
{
    char *buffer;
    size_t capacity;
    size_t used;
    size_t total;
} format_output_t;

static void format_char(format_output_t *out, char c)
{
    if (out->capacity != 0 && out->used + 1 < out->capacity)
    {
        out->buffer[out->used] = c;
    }

    ++out->used;
    ++out->total;
}

static void format_repeat(format_output_t *out, char c, int count)
{
    while (count-- > 0) format_char(out, c);
}

static void format_bytes(format_output_t *out, const char *s, size_t count)
{
    while (count-- != 0) format_char(out, *s++);
}

static int unsigned_digits(char *buffer, unsigned long long value,
                           unsigned base, int uppercase)
{
    const char *digits = uppercase
        ? "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"
        : "0123456789abcdefghijklmnopqrstuvwxyz";
    int count = 0;

    do
    {
        buffer[count++] = digits[value % base];
        value /= base;
    } while (value != 0);

    return count;
}

int vsnprintf(char *buffer, size_t capacity, const char *format, va_list args)
{
    format_output_t out;

    out.buffer = buffer;
    out.capacity = capacity;
    out.used = 0;
    out.total = 0;

    while (*format != '\0')
    {
        int left = 0;
        int plus = 0;
        int space = 0;
        int alternate = 0;
        int zero = 0;
        int width = 0;
        int precision = -1;
        int length = 0;
        char spec;

        if (*format != '%')
        {
            format_char(&out, *format++);
            continue;
        }

        ++format;

        for (;;)
        {
            if (*format == '-') left = 1;
            else if (*format == '+') plus = 1;
            else if (*format == ' ') space = 1;
            else if (*format == '#') alternate = 1;
            else if (*format == '0') zero = 1;
            else break;
            ++format;
        }

        if (*format == '*')
        {
            width = va_arg(args, int);
            ++format;
            if (width < 0) { left = 1; width = -width; }
        }
        else
        {
            while (isdigit((unsigned char) *format))
            {
                width = width * 10 + (*format++ - '0');
            }
        }

        if (*format == '.')
        {
            ++format;
            precision = 0;

            if (*format == '*')
            {
                precision = va_arg(args, int);
                ++format;
            }
            else
            {
                while (isdigit((unsigned char) *format))
                {
                    precision = precision * 10 + (*format++ - '0');
                }
            }
        }

        if (*format == 'h')
        {
            length = 1;
            ++format;
            if (*format == 'h') { length = 2; ++format; }
        }
        else if (*format == 'l')
        {
            length = 3;
            ++format;
            if (*format == 'l') { length = 4; ++format; }
        }
        else if (*format == 'z' || *format == 't')
        {
            length = 5;
            ++format;
        }

        spec = *format == '\0' ? '\0' : *format++;

        if (spec == '%')
        {
            format_char(&out, '%');
        }
        else if (spec == 'c')
        {
            char c = (char) va_arg(args, int);
            if (!left) format_repeat(&out, ' ', width - 1);
            format_char(&out, c);
            if (left) format_repeat(&out, ' ', width - 1);
        }
        else if (spec == 's')
        {
            const char *s = va_arg(args, const char *);
            size_t count;

            if (s == NULL) s = "(null)";
            count = strlen(s);
            if (precision >= 0 && count > (size_t) precision) count = precision;

            if (!left) format_repeat(&out, ' ', width - (int) count);
            format_bytes(&out, s, count);
            if (left) format_repeat(&out, ' ', width - (int) count);
        }
        else if (spec == 'd' || spec == 'i' || spec == 'u'
              || spec == 'x' || spec == 'X' || spec == 'o'
              || spec == 'p')
        {
            char digits[32];
            char prefix[3];
            int prefix_len = 0;
            int digit_count;
            int zero_count;
            int pad_count;
            unsigned base = 10;
            int uppercase = spec == 'X';
            unsigned long long value;
            int negative = 0;

            if (spec == 'x' || spec == 'X' || spec == 'p') base = 16;
            else if (spec == 'o') base = 8;

            if (spec == 'd' || spec == 'i')
            {
                long long signed_value;

                if (length == 4) signed_value = va_arg(args, long long);
                else if (length == 3) signed_value = va_arg(args, long);
                else signed_value = va_arg(args, int);

                if (length == 1) signed_value = (short) signed_value;
                else if (length == 2) signed_value = (signed char) signed_value;

                if (signed_value < 0)
                {
                    negative = 1;
                    value = (unsigned long long) (-(signed_value + 1)) + 1;
                }
                else
                {
                    value = (unsigned long long) signed_value;
                }
            }
            else if (spec == 'p')
            {
                value = (uintptr_t) va_arg(args, void *);
                alternate = 1;
            }
            else
            {
                if (length == 4) value = va_arg(args, unsigned long long);
                else if (length == 3) value = va_arg(args, unsigned long);
                else if (length == 5) value = va_arg(args, size_t);
                else value = va_arg(args, unsigned int);

                if (length == 1) value = (unsigned short) value;
                else if (length == 2) value = (unsigned char) value;
            }

            if (negative) prefix[prefix_len++] = '-';
            else if ((spec == 'd' || spec == 'i') && plus) prefix[prefix_len++] = '+';
            else if ((spec == 'd' || spec == 'i') && space) prefix[prefix_len++] = ' ';

            if (alternate && base == 16 && value != 0)
            {
                prefix[prefix_len++] = '0';
                prefix[prefix_len++] = uppercase ? 'X' : 'x';
            }
            else if (alternate && base == 8 && value != 0)
            {
                prefix[prefix_len++] = '0';
            }

            if (precision == 0 && value == 0)
            {
                digit_count = 0;
            }
            else
            {
                digit_count = unsigned_digits(digits, value, base, uppercase);
            }

            zero_count = precision > digit_count ? precision - digit_count : 0;

            if (zero && !left && precision < 0)
            {
                int wanted = width - prefix_len - digit_count;
                if (wanted > zero_count) zero_count = wanted;
            }

            pad_count = width - prefix_len - zero_count - digit_count;

            if (!left) format_repeat(&out, ' ', pad_count);
            format_bytes(&out, prefix, prefix_len);
            format_repeat(&out, '0', zero_count);
            while (digit_count-- > 0) format_char(&out, digits[digit_count]);
            if (left) format_repeat(&out, ' ', pad_count);
        }
        else if (spec == 'n')
        {
            int *target = va_arg(args, int *);
            if (target != NULL) *target = (int) out.total;
        }
        else if (spec == 'f' || spec == 'F' || spec == 'g' || spec == 'G')
        {
            /* Startup output does not depend on floating formatting.  Consume
             * the argument correctly and provide a compact, deterministic
             * representation for the occasional configuration diagnostic. */
            double value = va_arg(args, double);
            long whole = (long) value;
            char temporary[32];
            int count;

            if (value < 0 && whole == 0) format_char(&out, '-');
            count = unsigned_digits(temporary,
                                    whole < 0 ? (unsigned long) -whole
                                              : (unsigned long) whole,
                                    10, 0);
            if (whole < 0) format_char(&out, '-');
            while (count-- > 0) format_char(&out, temporary[count]);
        }
        else if (spec == '\0')
        {
            break;
        }
        else
        {
            format_char(&out, '%');
            format_char(&out, spec);
        }
    }

    if (capacity != 0)
    {
        size_t terminator = out.used < capacity ? out.used : capacity - 1;
        buffer[terminator] = '\0';
    }

    return (int) out.total;
}

int snprintf(char *buffer, size_t capacity, const char *format, ...)
{
    va_list args;
    int result;

    va_start(args, format);
    result = vsnprintf(buffer, capacity, format, args);
    va_end(args);
    return result;
}

int sprintf(char *buffer, const char *format, ...)
{
    va_list args;
    int result;

    va_start(args, format);
    result = vsnprintf(buffer, (size_t) -1, format, args);
    va_end(args);
    return result;
}

int vsprintf(char *buffer, const char *format, va_list args)
{
    return vsnprintf(buffer, (size_t) -1, format, args);
}

/* ------------------------------------------------------------------------- */
/* FILE interface                                                            */
/* ------------------------------------------------------------------------- */

typedef struct
{
    int fd;
    int eof;
    int error;
    int static_stream;
    int has_ungot;
    unsigned char ungot;
} mini_file_t;

static mini_file_t mini_stdin  = { 0, 0, 0, 1, 0, 0 };
static mini_file_t mini_stdout = { 1, 0, 0, 1, 0, 0 };
static mini_file_t mini_stderr = { 2, 0, 0, 1, 0, 0 };

#undef stdin
#undef stdout
#undef stderr
FILE *stdin  = (FILE *) &mini_stdin;
FILE *stdout = (FILE *) &mini_stdout;
FILE *stderr = (FILE *) &mini_stderr;

static mini_file_t *mini_file(FILE *stream)
{
    return (mini_file_t *) stream;
}

FILE *fopen(const char *path, const char *mode)
{
    int flags;
    int fd;
    mini_file_t *stream;

    if (path == NULL || mode == NULL)
    {
        errno = EINVAL;
        return NULL;
    }

    if (mode[0] == 'r')
    {
        flags = strchr(mode, '+') != NULL ? 2 : 0;
    }
    else if (mode[0] == 'w')
    {
        flags = strchr(mode, '+') != NULL ? (2 | 512) : (1 | 64 | 512);
    }
    else if (mode[0] == 'a')
    {
        flags = strchr(mode, '+') != NULL
              ? (2 | 512 | 1024) : (1 | 64 | 1024);
    }
    else
    {
        errno = EINVAL;
        return NULL;
    }

    fd = vm_syscall3(2, (uintptr_t) path, (uintptr_t) flags, 0666);

    if (fd < 0)
    {
        errno = ENOENT;
        return NULL;
    }

    stream = malloc(sizeof(*stream));

    if (stream == NULL)
    {
        vm_syscall3(3, (uintptr_t) fd, 0, 0);
        return NULL;
    }

    memset(stream, 0, sizeof(*stream));
    stream->fd = fd;
    return (FILE *) stream;
}

FILE *freopen(const char *path, const char *mode, FILE *stream)
{
    FILE *replacement;

    if (stream != NULL) fclose(stream);
    replacement = fopen(path, mode);
    return replacement;
}

int fclose(FILE *stream)
{
    mini_file_t *file;
    int result;

    if (stream == NULL)
    {
        errno = EINVAL;
        return EOF;
    }

    file = mini_file(stream);
    result = vm_syscall3(3, (uintptr_t) file->fd, 0, 0);

    if (!file->static_stream)
    {
        free(file);
    }

    return result < 0 ? EOF : 0;
}

size_t fread(void *ptr, size_t size, size_t count, FILE *stream)
{
    mini_file_t *file = mini_file(stream);
    size_t total;
    int result;

    if (size == 0 || count == 0) return 0;
    if (count > (size_t) -1 / size) return 0;

    total = size * count;
    result = vm_syscall3(0, (uintptr_t) file->fd, (uintptr_t) ptr, total);

    if (result < 0)
    {
        file->error = 1;
        return 0;
    }

    if ((size_t) result < total) file->eof = 1;
    return (size_t) result / size;
}

size_t fwrite(const void *ptr, size_t size, size_t count, FILE *stream)
{
    mini_file_t *file = mini_file(stream);
    size_t total;
    int result;

    if (size == 0 || count == 0) return 0;
    if (count > (size_t) -1 / size) return 0;

    total = size * count;
    result = vm_syscall3(1, (uintptr_t) file->fd, (uintptr_t) ptr, total);

    if (result < 0)
    {
        file->error = 1;
        return 0;
    }

    return (size_t) result / size;
}

int fflush(FILE *stream)
{
    (void) stream;
    return 0;
}

int fseek(FILE *stream, long offset, int whence)
{
    mini_file_t *file = mini_file(stream);
    int result = vm_syscall3(8, (uintptr_t) file->fd,
                            (uintptr_t) offset, (uintptr_t) whence);

    if (result < 0)
    {
        file->error = 1;
        return -1;
    }

    file->eof = 0;
    file->has_ungot = 0;
    return 0;
}

long ftell(FILE *stream)
{
    mini_file_t *file = mini_file(stream);
    return (long) vm_syscall3(8, (uintptr_t) file->fd, 0, 1);
}

void rewind(FILE *stream)
{
    (void) fseek(stream, 0, SEEK_SET);
    clearerr(stream);
}

int fgetc(FILE *stream)
{
    mini_file_t *file = mini_file(stream);
    unsigned char value;

    if (file->has_ungot)
    {
        file->has_ungot = 0;
        return file->ungot;
    }

    if (fread(&value, 1, 1, stream) != 1) return EOF;
    return value;
}

int getc(FILE *stream) { return fgetc(stream); }
int getchar(void) { return fgetc(stdin); }

int ungetc(int c, FILE *stream)
{
    mini_file_t *file = mini_file(stream);

    if (c == EOF || file->has_ungot) return EOF;
    file->ungot = (unsigned char) c;
    file->has_ungot = 1;
    file->eof = 0;
    return (unsigned char) c;
}

int fputc(int c, FILE *stream)
{
    unsigned char value = (unsigned char) c;
    return fwrite(&value, 1, 1, stream) == 1 ? value : EOF;
}

int putc(int c, FILE *stream) { return fputc(c, stream); }
int putchar(int c) { return fputc(c, stdout); }

char *fgets(char *s, int size, FILE *stream)
{
    int used = 0;

    if (size <= 0) return NULL;

    while (used + 1 < size)
    {
        int c = fgetc(stream);
        if (c == EOF) break;
        s[used++] = (char) c;
        if (c == '\n') break;
    }

    if (used == 0) return NULL;
    s[used] = '\0';
    return s;
}

int fputs(const char *s, FILE *stream)
{
    size_t length = strlen(s);
    return fwrite(s, 1, length, stream) == length ? 0 : EOF;
}

int puts(const char *s)
{
    if (fputs(s, stdout) == EOF || fputc('\n', stdout) == EOF) return EOF;
    return 0;
}

int vfprintf(FILE *stream, const char *format, va_list args)
{
    char buffer[2048];
    int result = vsnprintf(buffer, sizeof(buffer), format, args);
    size_t amount = result < 0 ? 0 : (size_t) result;

    if (amount >= sizeof(buffer)) amount = sizeof(buffer) - 1;
    if (fwrite(buffer, 1, amount, stream) != amount) return -1;
    return result;
}

int fprintf(FILE *stream, const char *format, ...)
{
    va_list args;
    int result;

    va_start(args, format);
    result = vfprintf(stream, format, args);
    va_end(args);
    return result;
}

int vprintf(const char *format, va_list args)
{
    return vfprintf(stdout, format, args);
}

int printf(const char *format, ...)
{
    va_list args;
    int result;

    va_start(args, format);
    result = vfprintf(stdout, format, args);
    va_end(args);
    return result;
}

int feof(FILE *stream) { return mini_file(stream)->eof; }
int ferror(FILE *stream) { return mini_file(stream)->error; }
void clearerr(FILE *stream)
{
    mini_file(stream)->eof = 0;
    mini_file(stream)->error = 0;
}

int fileno(FILE *stream) { return mini_file(stream)->fd; }
void setbuf(FILE *stream, char *buffer) { (void) stream; (void) buffer; }
int setvbuf(FILE *stream, char *buffer, int mode, size_t size)
{
    (void) stream; (void) buffer; (void) mode; (void) size;
    return 0;
}

int remove(const char *path)
{
    (void) path;
    errno = ENOSYS;
    return -1;
}

int rename(const char *old_path, const char *new_path)
{
    return vm_syscall3(38, (uintptr_t) old_path, (uintptr_t) new_path, 0);
}

/* ------------------------------------------------------------------------- */
/* scanning                                                                  */
/* ------------------------------------------------------------------------- */

static int scan_string(const char *input, const char *format, va_list args)
{
    int assigned = 0;

    while (*format != '\0')
    {
        if (isspace((unsigned char) *format))
        {
            while (isspace((unsigned char) *format)) ++format;
            while (isspace((unsigned char) *input)) ++input;
            continue;
        }

        if (*format != '%')
        {
            if (*input != *format) break;
            ++input;
            ++format;
            continue;
        }

        ++format;

        if (*format == '%')
        {
            if (*input != '%') break;
            ++input;
            ++format;
            continue;
        }

        {
            int suppress = 0;
            int width = 0;
            char spec;
            char *end;

            if (*format == '*') { suppress = 1; ++format; }
            while (isdigit((unsigned char) *format))
                width = width * 10 + (*format++ - '0');
