void qsort(void *base, size_t count, size_t size,
           int (*compare)(const void *, const void *))
{
    unsigned char *bytes = base;
    size_t i;
    unsigned char *temporary;

    if (count < 2 || size == 0) return;
    temporary = malloc(size);
    if (temporary == NULL) return;

    for (i = 1; i < count; ++i)
    {
        size_t j = i;
        memcpy(temporary, bytes + i * size, size);

        while (j > 0 && compare(bytes + (j - 1) * size, temporary) > 0)
        {
            memcpy(bytes + j * size, bytes + (j - 1) * size, size);
            --j;
        }

        memcpy(bytes + j * size, temporary, size);
    }

    free(temporary);
}

void *bsearch(const void *key, const void *base, size_t count, size_t size,
              int (*compare)(const void *, const void *))
{
    const unsigned char *bytes = base;
    size_t low = 0;
    size_t high = count;

    while (low < high)
    {
        size_t middle = low + (high - low) / 2;
        const void *entry = bytes + middle * size;
        int order = compare(key, entry);

        if (order == 0) return (void *) entry;
        if (order < 0) high = middle;
        else low = middle + 1;
    }

    return NULL;
}

